def fibonacci_iterativo(n):
    """Devuelve F(n) con un bucle: O(n) tiempo y O(1) memoria."""
    anterior, actual = 0, 1
    for _ in range(n):
        anterior, actual = actual, anterior + actual
    return anterior


def fibonacci_memo(n, memo=None):
    """Devuelve F(n) recursivamente, guardando los resultados en memo."""
    if memo is None:
        memo = {}
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fibonacci_memo(n - 1, memo) + fibonacci_memo(n - 2, memo)
    return memo[n]


def serie_fibonacci(n):
    """Devuelve la lista [F(0), F(1), ..., F(n-1)]."""
    serie = []
    anterior, actual = 0, 1
    for _ in range(n):
        serie.append(anterior)
        anterior, actual = actual, anterior + actual
    return serie

