def aplanar(anidada):
    """Devuelve una lista plana con los elementos no-lista, en orden."""
    plana = []
    for elemento in anidada:
        if isinstance(elemento, list):
            plana.extend(aplanar(elemento))   # caso recursivo
        else:
            plana.append(elemento)            # caso base: un elemento simple
    return plana


def profundidad(dato):
    """Devuelve el nivel máximo de anidamiento de listas (0 si no es lista)."""
    if not isinstance(dato, list):
        return 0
    maxima = 0
    for elemento in dato:
        maxima = max(maxima, profundidad(elemento))
    return 1 + maxima

