def es_solucion_valida(n, movimientos, origen="A", destino="C", auxiliar="B"):
    """Simula los movimientos y comprueba que son legales y terminan en destino."""
    varillas = {origen: list(range(n, 0, -1)), destino: [], auxiliar: []}
    for desde, hasta in movimientos:
        if not varillas[desde]:
            return False
        disco = varillas[desde].pop()
        if varillas[hasta] and varillas[hasta][-1] < disco:
            return False
        varillas[hasta].append(disco)
    return varillas[destino] == list(range(n, 0, -1))

