exercises.solution:
def media(datos):
    """Devuelve la media aritmética o None si no hay datos."""
    if not datos:
        return None
    return sum(datos) / len(datos)


def mediana(datos):
    """Devuelve el valor central de los datos ordenados o None si no hay datos."""
    if not datos:
        return None
    ordenados = sorted(datos)          # sorted: no toca la lista original
    mitad = len(ordenados) // 2
    if len(ordenados) % 2 == 1:
        return ordenados[mitad]
    return (ordenados[mitad - 1] + ordenados[mitad]) / 2


def moda(datos):
    """Devuelve la lista ordenada de los valores más frecuentes."""
    if not datos:
        return []
    frecuencias = {}
    for valor in datos:
        frecuencias[valor] = frecuencias.get(valor, 0) + 1
    maxima = max(frecuencias.values())
    return sorted([valor for valor, veces in frecuencias.items() if veces == maxima])


def varianza(datos, *, muestral=False):
    """Devuelve la varianza poblacional (o muestral) o None si no se puede calcular."""
    n = len(datos)
    if n == 0 or (muestral and n < 2):
        return None
    m = media(datos)
    suma_cuadrados = sum([(x - m) ** 2 for x in datos])
    divisor = n - 1 if muestral else n
    return suma_cuadrados / divisor


def desviacion(datos, *, muestral=False):
    """Devuelve la desviación típica o None si no se puede calcular."""
    v = varianza(datos, muestral=muestral)
    if v is None:
        return None
    return v ** 0.5


def _redondear(valor, decimales):
    if valor is None:
        return None
    return round(valor, decimales)


def resumen(datos, *, decimales=2):
    """Devuelve un diccionario con las principales medidas de los datos."""
    return {
        "n": len(datos),
        "media": _redondear(media(datos), decimales),
        "mediana": _redondear(mediana(datos), decimales),
        "moda": moda(datos),
        "desviacion": _redondear(desviacion(datos), decimales),
    }

