exercises.solution:
def sumar(*valores):
    return sum(valores)


def multiplicar(*valores):
    resultado = 1
    for valor in valores:
        resultado *= valor
    return resultado


def restar(primero, *resto):
    if not resto:
        return -primero
    for valor in resto:
        primero -= valor
    return primero


def dividir(primero, *resto):
    for valor in resto:
        primero /= valor
    return primero


def maximo(*valores):
    return max(valores)    # max(valores) y no max(*valores): funciona con un solo valor


def minimo(*valores):
    return min(valores)


OPERADORES = {
    "+": sumar,
    "*": multiplicar,
    "-": restar,
    "/": dividir,
    "max": maximo,
    "min": minimo,
}


def evaluar(expr, variables=None):
    """Evalúa una expresión anidada y devuelve su valor numérico."""
    if variables is None:
        variables = {}
    if isinstance(expr, str):
        return variables[expr]                 # KeyError si la variable no existe
    if isinstance(expr, list):
        operador, *argumentos = expr
        funcion = OPERADORES[operador]         # KeyError si el operador no existe
        valores = [evaluar(arg, variables) for arg in argumentos]
        return funcion(*valores)
    return expr                                # un número se evalúa a sí mismo


def a_texto(expr):
    """Devuelve la expresión en notación habitual con paréntesis."""
    if not isinstance(expr, list):
        return str(expr)
    operador, *argumentos = expr
    partes = [a_texto(arg) for arg in argumentos]
    if operador in ("max", "min"):
        return f"{operador}({', '.join(partes)})"
    if operador == "-" and len(partes) == 1:
        return f"(-{partes[0]})"
    return "(" + f" {operador} ".join(partes) + ")"


def recoger_variables(expr, encontradas):
    """Añade al conjunto encontradas las variables de expr."""
    if isinstance(expr, str):
        encontradas.add(expr)
    elif isinstance(expr, list):
        for arg in expr[1:]:
            recoger_variables(arg, encontradas)


def variables_usadas(expr):
    """Devuelve la lista ordenada y sin repetidos de variables de la expresión."""
    encontradas = set()
    recoger_variables(expr, encontradas)
    return sorted(encontradas)

